  karin_margit:{name:"Karin Margit Johansson",alt:"g. Bengtsson",role:"Mormor",born:"1929-02-11",died:"2023-10",status:"confirmed",place:"Morup / Klastorp",facts:[["Liv","Flyttade till Klastorp på 1950-talet"],["Avvikelse","Ancestry-skärmbilden visar 1929-2022, men familjeuppgift anger oktober 2023"],["Nästa steg","Komplettera exakt dödsdatum och källa"]],story:["Karin Margit föds 11 februari 1929 i Morup enligt den senaste morfarsfilen. Hon bär flicknamnet Johansson och tar som gift namnet Bengtsson.","På 1950-talet flyttar hon med Axel Harry Bengtsson till Klastorp. Tillsammans får de barnen Ingemar och Gerd.","Den senaste morfarsfilen anger att familjeuppgiften om död i oktober 2023 ska ges företräde framför Ancestry-trädets 2022-uppgift tills exakt källa kompletteras."],timeline:[["1929-02-11","Föds i Morup enligt senaste morfarsfilen."],["1950-talet","Flyttar med Harry Bengtsson till Klastorp."],["2023-10","Avlider enligt familjeuppgift; exakt datum ska kompletteras."]],parents:["karl_hjalmar_johansson","ester_viktoria"],children:["ingemar_bengtsson","gerd_bengtsson"]},
  harry_bengtsson:{name:"Axel Harry Bengtsson",alt:"Harry Bengtsson",role:"Morfar",born:"1916-12-22",died:"1998",status:"confirmed",place:"Klastorp",facts:[["Födelseort","Klastorp"],["Maka","Karin Margit Johansson"],["Barn","Ingemar och Gerd Bengtsson"],["Föräldrar","Sven Adolf Bengtsson och Gertrud Persdotter"],["Källstatus","Födelsedatum och födelseort finns som arbetsuppgift; originalnotis ska dokumenteras"]],story:["Axel Harry Bengtsson föds 22 december 1916 i Klastorp och avlider 1998.","Den senaste morfarsfilen kopplar honom preliminärt till föräldrarna Sven Adolf Bengtsson och Gertrud Persdotter. Födelsenotisen 1916 är prioriterad nästa kontroll för att låsa föräldrarna i originalkälla.","Harry gifter sig med Karin Margit Johansson. Tillsammans får de barnen Ingemar och Gerd Bengtsson."],parents:["sven_adolf_bengtsson","gertrud_persdotter"],children:["ingemar_bengtsson","gerd_bengtsson"]},
  sven_adolf_bengtsson:{name:"Sven Adolf Bengtsson",role:"Morfars far",born:"1879",died:"1962",status:"working",facts:[["Maka","Gertrud Persdotter"],["Barn","Axel Harry Bengtsson"],["Föräldrar enligt Ancestry-trädet","Bengt A. Nilsson och Sara Britta Andersdotter"],["Källstatus","Preliminär; födelsenotis och familj ska kontrolleras"]],story:["Sven Adolf Bengtsson förs i senaste morfarsfilen som far till Axel Harry Bengtsson.","Uppgiften kommer från Ancestry-trädet och ska kontrolleras mot födelsenotis, församlingsbok och familjen när Harry föds i Klastorp 1916."],parents:["bengt_a_nilsson","sara_britta_andersdotter"],children:["harry_bengtsson"]},
  gertrud_persdotter:{name:"Gertrud Persdotter",role:"Morfars mor",born:"1875",died:"1951",status:"working",facts:[["Make","Sven Adolf Bengtsson"],["Barn","Axel Harry Bengtsson"],["Källstatus","Preliminär från Ancestry-träd"]],story:["Gertrud Persdotter förs som mor till Axel Harry Bengtsson i senaste morfarsfilen.","Uppgiften är preliminär tills Harrys födelsenotis och familjens församlingsbok har kontrollerats."],parents:[],children:["harry_bengtsson"]},
  bengt_a_nilsson:{name:"Bengt A. Nilsson",role:"Morfars farfar",born:"1840",died:"1926",status:"working",facts:[["Maka","Sara Britta Andersdotter"],["Barn","Nils Johan, Anders G., Karl Oskar, Johan Albin, Alma J., Anna V., Sven Adolf och Lars Emil"],["Föräldrar enligt Ancestry-trädet","Nils Bengtsson och Gunnild Alfredsdotter"],["Anmärkning","Mellannamnet bakom initialen A. är ännu okänt"]],story:["Bengt A. Nilsson förs i morfarsfilen som far till Sven Adolf Bengtsson och make till Sara Britta Andersdotter.","Barnaskaran i Ancestry-trädet omfattar åtta kända barn födda mellan 1865 och 1885. Samtliga barns fullständiga datum, födelseorter och koppling till föräldraparet ska kontrolleras."],parents:["nils_bengtsson_1814","gunnild_alfredsdotter"],children:["nils_johan_bengtsson","anders_g_bengtsson","karl_oskar_bengtsson","johan_albin_bengtsson","alma_j_bengtsdotter","anna_v_bengtsdotter","sven_adolf_bengtsson","lars_emil_bengtsson"]},
  sara_britta_andersdotter:{name:"Sara Britta Andersdotter",role:"Morfars farmor",born:"1840",died:"1918",status:"working",facts:[["Make","Bengt A. Nilsson"],["Källstatus","Preliminär från Ancestry-träd"]],story:["Sara Britta Andersdotter förs som maka till Bengt A. Nilsson och mor till Sven Adolf Bengtsson i senaste morfarsfilen.","Uppgifterna är preliminära och behöver kontrolleras i vigselbok, husförhör/församlingsbok och barnens födelsenotiser."],parents:[],children:["nils_johan_bengtsson","anders_g_bengtsson","karl_oskar_bengtsson","johan_albin_bengtsson","alma_j_bengtsdotter","anna_v_bengtsdotter","sven_adolf_bengtsson","lars_emil_bengtsson"]},
