  bengt_olofsson_1772:{name:"Bengt Olofsson",role:"Barn i Karins första äktenskap",born:"1772-11-27",status:"working",place:"Träslöv",story:["Bengt förs som barn till Olof Bengtsson och Karin Svensdotter enligt födelseindex. Han är sannolikt namngiven efter en äldre bror Bengt som avlidit före 1772."],parents:["olof_bengtsson_forsta","karin_svensdotter_1741"],children:[]},
