  anna_josefina_gustafsdotter:{name:"Anna Josefina",role:"Syskon till Nils Birger",born:"1888-12-10",status:"confirmed",place:"Årstad",story:["Anna Josefina förekommer som dotter i hushållet med Gustaf Henning Johansson och Augusta Olivia Larsdotter i Fjellalunda."],parents:["gustaf_henning_johansson","augusta_olivia_larsdotter"],children:[]},
