  hilma_elisabeth_gustafsdotter:{name:"Hilma Elisabeth",role:"Syskon till Nils Birger",born:"1892-02-27",status:"confirmed",place:"Årstad",story:["Hilma Elisabeth förekommer som dotter i hushållet med Gustaf Henning Johansson och Augusta Olivia Larsdotter i Fjellalunda och senare på sida 425."],parents:["gustaf_henning_johansson","augusta_olivia_larsdotter"],children:[]},
